+static const char *
+skip_enclosed_container(const char *signature, char open_bracket, char closed_bracket) {
+	int nested = 0;
+	for (char sig_code = *signature++; sig_code != '\0'; sig_code = *signature++) {
+		if (sig_code == closed_bracket) {
+			if (nested == 0) {
+				return signature;
+			}
+			nested--;
+		} else if (sig_code == open_bracket) {
+			nested++;
+		}
+	}
+	return NULL;
+}
